package com.vasiliyrogozhin85.upospa;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;
public class DashboardActivity extends Activity{
 private TextView summary; public void onCreate(Bundle b){super.onCreate(b);UiKit.screen(this);setContentView(ui());refresh();}
 private View ui(){ScrollView s=new ScrollView(this);s.setBackgroundColor(UiKit.BG);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(UiKit.dp(this,16),UiKit.dp(this,14),UiKit.dp(this,16),UiKit.dp(this,28));s.addView(r);TextView back=UiKit.tv(this,"‹  uPOSPa • DASHBOARD",25,UiKit.TEXT,true);back.setOnClickListener(v->finish());r.addView(back);r.addView(UiKit.tv(this,"состояние устройства • диагностика • установка",13,UiKit.MUTED,false));summary=UiKit.tv(this,"Сбор данных…",14,UiKit.TEXT,false);r.addView(UiKit.card(this,summary),UiKit.top(this,12));r.addView(UiKit.section(this,"Быстрые действия"));r.addView(UiKit.button(this,"▤  Полная диагностика",UiKit.CLIENT,v->collect()));r.addView(UiKit.button(this,"▣  HOST",UiKit.HOST,v->startActivity(new Intent(this,HostActivity.class))));r.addView(UiKit.button(this,"▯  CLIENT",UiKit.CLIENT,v->startActivity(new Intent(this,ClientActivity.class))));r.addView(UiKit.button(this,"⚡  SERVICE / FASTBOOT",UiKit.WARN,v->startActivity(new Intent(this,ServiceActivity.class))));r.addView(UiKit.darkButton(this,"▤  Единый отчёт",v->startActivity(new Intent(this,ReportActivity.class))));r.addView(UiKit.darkButton(this,"◴  История устройств",v->startActivity(new Intent(this,HistoryActivity.class))));r.addView(UiKit.darkButton(this,"⚙  Аппаратные тесты",v->startActivity(new Intent(this,HardwareTestActivity.class))));r.addView(UiKit.darkButton(this,"▦  Библиотека пакетов",v->startActivity(new Intent(this,PackageLibraryActivity.class))));return s;}
 private void refresh(){new Thread(()->{try{JSONObject j=DeviceSnapshot.collect(this);JSONObject d=j.optJSONObject("device"),a=j.optJSONObject("android"),bat=j.optJSONObject("battery"),p=j.optJSONObject("system_properties");JSONObject o=OemProfileEngine.profile(j);String x=(d==null?"":d.optString("manufacturer")+" "+d.optString("model"))+"\nAndroid "+(a==null?"?":a.optString("release"))+" • "+(d==null?"":d.optString("device"))+"\nБатарея: "+(bat==null?"?":bat.optInt("capacity_percent",-1))+"%\nVerified Boot: "+(p==null?"?":p.optString("ro.boot.verifiedbootstate","?"))+"\nOEM профиль: "+o.optString("family","generic")+"\n"+o.optString("notes","");runOnUiThread(()->summary.setText(x));}catch(Exception e){runOnUiThread(()->summary.setText("Ошибка диагностики: "+e));}}).start();}
 private void collect(){new Thread(()->{try{JSONObject j=DeviceSnapshot.collect(this);File f=DeviceSnapshot.write(this,j);new DeviceHistoryStore(this).add(j,"dashboard");runOnUiThread(()->new AlertDialog.Builder(this).setTitle("Отчёт создан").setMessage(f.getAbsolutePath()).setPositiveButton("OK",null).show());}catch(Exception e){}}).start();}
}
